package graph

import (
	"fmt"
	"slices"
	"strings"
	"text/template"
	"unicode"

	"github.com/tylergannon/gimble/workflow"
)

// source prints the workflow's generated file as Go: its graph, registered
// from an init, and its gimble run subcommand, with a local and a flag for
// each field of the input, a model flag for each role the graph names, the
// web application's flags, and a RunE that fills the input, binds the
// roles, starts the runtime, and calls the entry.
func source(pkg, entry string, info entryInfo, graph workflow.Graph) string {
	data := commandData{Package: pkg, Name: graph.Name, Entry: entry, Input: info.input, Summary: info.summary, Long: info.long, Graph: literal(entry, graph)}
	for _, f := range info.fields {
		cf := commandField{Name: f.name, Flag: f.flag, Kind: f.kind, Optional: f.optional, Usage: f.doc}
		cf.Var, cf.Default = map[string]string{"string": "StringVar", "int": "IntVar", "bool": "BoolVar"}[f.kind], map[string]string{"string": `""`, "int": "0", "bool": "false"}[f.kind]
		cf.Target = "&in." + f.name
		if f.optional {
			cf.Target = "&opt" + f.name
			data.Optional = true
		}
		if f.name == "Repo" && f.kind == "string" && !f.optional {
			cf.Default = `"."`
			data.Repo = true
		}
		if cf.Required = !f.optional && f.kind != "bool" && cf.Default != `"."`; cf.Required {
			cf.Usage += " (required)"
		}
		data.Fields = append(data.Fields, cf)
	}
	for _, role := range graph.Roles() {
		data.Roles = append(data.Roles, commandRole{Name: role, Ident: identifier(role) + "Model", Default: info.defaults[role], Usage: "the model for role " + role + ", as model or model:effort"})
	}
	var b strings.Builder
	if err := commandTemplate.Execute(&b, data); err != nil {
		panic(err)
	}
	return b.String()
}

// check refuses a command whose flags would collide: an input field or a
// role named like a flag every command has, or like each other; and a roles
// entry for a role the workflow never creates a session for.
func check(info entryInfo, graph workflow.Graph) error {
	taken := map[string]string{"port": "the web application", "uds": "the web application", "no-web": "the web application", "help": "cobra"}
	for _, f := range info.fields {
		if by, ok := taken[f.flag]; ok {
			return fmt.Errorf("graph: the input field %s would be --%s, which is %s's", f.name, f.flag, by)
		}
		taken[f.flag] = "the input"
	}
	roles := graph.Roles()
	for _, role := range roles {
		if by, ok := taken[role]; ok {
			return fmt.Errorf("graph: the role %s would be --%s, which is %s's", role, role, by)
		}
	}
	for role := range info.defaults {
		if !slices.Contains(roles, role) {
			return fmt.Errorf("graph: roles gives %s a model, but %s creates no session for that role", role, graph.Name)
		}
	}
	return nil
}

// identifier is a role's name as a Go identifier: code-reviewer is codeReviewer.
func identifier(name string) string {
	var b strings.Builder
	upper := false
	for _, r := range name {
		switch {
		case unicode.IsLetter(r) || (unicode.IsDigit(r) && b.Len() > 0):
			if upper {
				r = unicode.ToUpper(r)
			}
			b.WriteRune(r)
			upper = false
		default:
			upper = b.Len() > 0
		}
	}
	return b.String()
}

type commandData struct {
	Package, Name, Entry, Input, Summary, Long, Graph string
	Fields                                            []commandField
	Roles                                             []commandRole
	Repo, Optional                                    bool
}

type commandField struct {
	Name, Flag, Kind, Var, Target, Default, Usage string
	Optional, Required                            bool
}

type commandRole struct{ Name, Ident, Default, Usage string }

var commandTemplate = template.Must(template.New("command").Parse(`// Code generated by gimble gen. DO NOT EDIT.

package {{.Package}}

import (
	"context"
	"os"
	"os/signal"
	"path/filepath"

	"github.com/spf13/cobra"
	"github.com/tylergannon/gimble"
	"github.com/tylergannon/gimble/internal/binding"
	"github.com/tylergannon/gimble/web"
	"github.com/tylergannon/gimble/workflow"
{{- if .Optional}}
	"github.com/tylergannon/polytype"
{{- end}}
)

func init() { gimble.RegisterGraph(Graph) }

{{.Graph}}
// Command is gimble run {{.Name}}: {{if .Input}}a flag for each field of {{.Input}}, {{end}}a
// model flag for each role {{.Entry}} names, with the default roles gives it,
// the web application's flags, and a run of {{.Entry}} on the runtime.
func Command() *cobra.Command {
{{- if .Input}}
	var in {{.Input}}
{{- end}}
{{- range .Fields}}{{if .Optional}}
	var opt{{.Name}} {{.Kind}}
{{- end}}{{end}}
{{- range .Roles}}
	var {{.Ident}} string
{{- end}}
	var port int
	var uds string
	var noWeb bool
	cmd := &cobra.Command{
		Use:   {{printf "%q" .Name}},
		Short: {{printf "%q" .Summary}},
		Long:  {{printf "%q" .Long}},
		Args:  cobra.NoArgs,
	}
{{- range .Fields}}
	cmd.Flags().{{.Var}}({{.Target}}, {{printf "%q" .Flag}}, {{.Default}}, {{printf "%q" .Usage}})
{{- end}}
{{- range .Fields}}{{if .Required}}
	_ = cmd.MarkFlagRequired({{printf "%q" .Flag}})
{{- end}}{{end}}
{{- range .Roles}}
	cmd.Flags().StringVar(&{{.Ident}}, {{printf "%q" .Name}}, {{printf "%q" .Default}}, {{printf "%q" .Usage}})
{{- if not .Default}}
	_ = cmd.MarkFlagRequired({{printf "%q" .Name}})
{{- end}}
{{- end}}
	cmd.Flags().IntVar(&port, "port", 8080, "loopback TCP port for the web application")
	cmd.Flags().StringVar(&uds, "uds", "", "Unix-domain socket for the web application instead of TCP")
	cmd.Flags().BoolVar(&noWeb, "no-web", false, "run without the web application")
	cmd.RunE = func(cmd *cobra.Command, _ []string) error {
{{- range .Fields}}{{if .Optional}}
		if cmd.Flags().Changed({{printf "%q" .Flag}}) {
			in.{{.Name}} = polytype.Optional[{{.Kind}}]{Present: true, Value: opt{{.Name}}}
		}
{{- end}}{{end}}
		repo, err := filepath.Abs({{if .Repo}}in.Repo{{else}}"."{{end}})
		if err != nil {
			return err
		}
{{- if .Repo}}
		in.Repo = repo
{{- end}}
		models, err := binding.Roles(map[string]string{ {{range .Roles}}{{printf "%q" .Name}}: {{.Ident}}, {{end}}})
		if err != nil {
			return err
		}
		ctx, stop := signal.NotifyContext(cmd.Context(), os.Interrupt)
		defer stop()
		var options []web.Option
		switch {
		case noWeb:
			options = append(options, web.WithNoWeb())
		case uds != "":
			options = append(options, web.WithUDS(uds))
		default:
			options = append(options, web.WithPort(port))
		}
		runtime, err := web.NewRuntime(ctx, filepath.Join(repo, ".gimble"), options...)
		if err != nil {
			return err
		}
		return runtime.Run(ctx, {{printf "%q" .Name}}, models, func(ctx context.Context) error { return {{.Entry}}(ctx{{if .Input}}, in{{end}}) })
	}
	return cmd
}
`))
